
const WORDS=[{"id": 0, "w": "事物", "p": "shìwù", "t": "名词", "m": "sự vật", "coll": "认识事物、事物的发展", "s": "我们看待事物时，要从不同的角度思考。"}, {"id": 1, "w": "高峰", "p": "gāofēng", "t": "名词", "m": "đỉnh cao, cao điểm", "coll": "交通高峰、事业的高峰", "s": "早上八点左右是这条路的交通高峰，车辆比较多。"}, {"id": 2, "w": "终点", "p": "zhōngdiǎn", "t": "名词", "m": "điểm cuối cùng, điểm kết thúc", "coll": "到达终点、比赛终点", "s": "跑了很长一段路后，她终于到达了终点。"}, {"id": 3, "w": "迅速", "p": "xùnsù", "t": "形容词", "m": "nhanh chóng", "coll": "迅速发展、迅速回答", "s": "听到消息后，他迅速赶到了学校。"}, {"id": 4, "w": "深刻", "p": "shēnkè", "t": "形容词", "m": "sâu sắc", "coll": "印象深刻、深刻理解", "s": "这次旅行给我留下了深刻的印象。"}, {"id": 5, "w": "戏剧", "p": "xìjù", "t": "名词", "m": "kịch, vở tuồng", "coll": "戏剧表演、观看戏剧", "s": "周末，我们一起去剧院观看了一场戏剧。"}, {"id": 6, "w": "投入", "p": "tóurù", "t": "动词／名词／形容词", "m": "đưa vào, bỏ vốn; kinh phí đầu tư; xuất thần", "coll": "投入时间、投入工作", "s": "为了完成这个项目，大家投入了很多时间。"}, {"id": 7, "w": "服装", "p": "fúzhuāng", "t": "名词", "m": "trang phục", "coll": "传统服装、舞台服装", "s": "参加表演前，演员们换上了舞台服装。"}, {"id": 8, "w": "化妆", "p": "huà zhuāng", "t": "动词", "m": "trang điểm", "coll": "化妆用品、化妆打扮", "s": "演出开始前，她正在后台化妆。"}, {"id": 9, "w": "道具", "p": "dàojù", "t": "名词", "m": "đạo cụ", "coll": "准备道具、舞台道具", "s": "演出前，工作人员认真检查了每一件道具。"}, {"id": 10, "w": "美术", "p": "měishù", "t": "名词", "m": "nghệ thuật tạo hình", "coll": "美术老师、美术作品", "s": "这幅画是一位学生的美术作品。"}, {"id": 11, "w": "以", "p": "yǐ", "t": "连词", "m": "để, nhằm", "coll": "以便、以免", "s": "我们先整理好资料，以便进行下一步讨论。"}, {"id": 12, "w": "良好", "p": "liánghǎo", "t": "形容词", "m": "tốt đẹp, tốt", "coll": "良好的习惯、良好的关系", "s": "坚持阅读有助于养成良好的学习习惯。"}, {"id": 13, "w": "争取", "p": "zhēngqǔ", "t": "动词", "m": "cố gắng, tranh thủ, giành", "coll": "争取机会、争取进步", "s": "他希望通过自己的努力，争取更多学习机会。"}, {"id": 14, "w": "忽视", "p": "hūshì", "t": "动词", "m": "xem nhẹ, không chú ý", "coll": "忽视细节、不能忽视", "s": "做决定时，我们不能忽视这些细节。"}, {"id": 15, "w": "魅力", "p": "mèilì", "t": "名词", "m": "sức hấp dẫn", "coll": "独特的魅力、展现魅力", "s": "这座城市有着独特的文化魅力。"}, {"id": 16, "w": "糟糕", "p": "zāogāo", "t": "形容词", "m": "tồi tệ, hỏng bét", "coll": "天气糟糕、心情糟糕", "s": "因为下雨，原来的旅行计划变得有些糟糕。"}, {"id": 17, "w": "婚礼", "p": "hūnlǐ", "t": "名词", "m": "lễ cưới", "coll": "参加婚礼、举行婚礼", "s": "周末，我们一起参加了朋友的婚礼。"}, {"id": 18, "w": "等于", "p": "děngyú", "t": "动词", "m": "bằng", "coll": "等于零、三加二等于五", "s": "三加二等于五，你算对了吗？"}, {"id": 19, "w": "度过", "p": "dùguò", "t": "动词", "m": "trải qua", "coll": "度过假期、度过难关", "s": "这个暑假，她和家人一起度过了愉快的时光。"}, {"id": 20, "w": "告别", "p": "gàobié", "t": "动词", "m": "tạm biệt, từ biệt", "coll": "告别朋友、挥手告别", "s": "离开学校时，他向老师和同学挥手告别。"}, {"id": 21, "w": "平常", "p": "píngcháng", "t": "形容词／名词", "m": "bình thường; ngày thường", "coll": "平常的日子、平常喜欢", "s": "平常，她喜欢在晚饭后散步。"}, {"id": 22, "w": "依然", "p": "yīrán", "t": "副词", "m": "vẫn, vẫn như cũ", "coll": "依然记得、依然美丽", "s": "虽然多年没有见面，我依然记得他的名字。"}, {"id": 23, "w": "推荐", "p": "tuījiàn", "t": "动词", "m": "giới thiệu, tiến cử", "coll": "推荐一本书、推荐朋友", "s": "老师向我们推荐了一本有趣的小说。"}, {"id": 24, "w": "淋漓尽致", "p": "línlí jìnzhì", "t": "成语", "m": "tinh tế, triệt để", "coll": "表现得淋漓尽致、发挥得淋漓尽致", "s": "演员把角色的感情表现得淋漓尽致。"}, {"id": 25, "w": "评价", "p": "píngjià", "t": "动词／名词", "m": "đánh giá; sự đánh giá", "coll": "评价作品、客观评价", "s": "看完电影后，同学们对这部作品作出了不同的评价。"}, {"id": 26, "w": "烂", "p": "làn", "t": "形容词", "m": "dở, tệ, thối rữa, rách nát", "coll": "水果烂了、菜叶烂了", "s": "这个苹果放了太久，已经烂了。"}, {"id": 27, "w": "主持", "p": "zhǔchí", "t": "动词／名词", "m": "chủ trì; người chủ trì", "coll": "主持会议、主持活动", "s": "今天的班会由班长主持。"}, {"id": 28, "w": "运用", "p": "yùnyòng", "t": "动词", "m": "vận dụng, áp dụng", "coll": "运用知识、灵活运用", "s": "老师鼓励我们灵活运用学过的知识。"}, {"id": 29, "w": "开幕式", "p": "kāimùshì", "t": "名词", "m": "lễ khai mạc", "coll": "参加开幕式、举行开幕式", "s": "运动会开始前，学校举行了开幕式。"}, {"id": 30, "w": "宁可", "p": "nìngkě", "t": "副词", "m": "thà rằng, thà", "coll": "宁可……也不……、宁可慢一点", "s": "他宁可多花一点时间，也不愿意随便完成工作。"}, {"id": 31, "w": "集中", "p": "jízhōng", "t": "动词／形容词", "m": "tập trung; chăm chú", "coll": "集中注意力、集中精力", "s": "上课时，我们应该集中注意力。"}, {"id": 32, "w": "体会", "p": "tǐhuì", "t": "动词／名词", "m": "hiểu rõ, nhận thức", "coll": "体会感情、亲身体会", "s": "通过这次活动，她体会到了帮助别人的快乐。"}];
